export const defaultView=()=>({from:1992,to:2027,benchmark:'CPI',inspect:2027});
export function validateView(v){return v&&Number.isInteger(v.from)&&Number.isInteger(v.to)&&v.from>=1992&&v.to<=2027&&v.from<v.to&&['CPI','MEI'].includes(v.benchmark)&&Number.isInteger(v.inspect)&&v.inspect>=v.from&&v.inspect<=v.to&&Object.keys(v).every(k=>['from','to','benchmark','inspect'].includes(k));}
